# -*- coding: utf-8 -*-
"""Part 4: Meta business and ad accounts, usernames, Snapchat, the hub."""
from c_en3 import *

page('meta-business-verification-documents-uk-eu-us', 'ad', 'Meta Business Verification Documents for UK, EU and US',
 'Which documents Meta accepts for business verification, with examples for UK, EU and US companies, and why verification gets rejected.',
 'Which documents does Meta accept for business verification?', 'Business verification documents',
 'Most rejections come from a mismatch: the legal name, address or phone on the document does not match what you entered.',
 'Meta business verification needs an official document showing your legal business name, plus proof of address or phone. UK companies often use a Companies House certificate, EU businesses a commercial register extract such as KvK or Handelsregister, and US businesses articles of incorporation or an EIN letter. The legal name must match exactly what you entered.',
 [('Legal name', 'Must match the document exactly.'), ('Address or phone', 'A utility bill or bank statement helps.'), ('Domain', 'A business email on your domain speeds things up.')],
 [S('Examples by country', ul(['United Kingdom: Companies House certificate of incorporation, VAT registration, or a utility bill in the company name.',
        'Netherlands: KvK extract. Germany: Handelsregisterauszug or Gewerbeanmeldung. France: Kbis extract.',
        'United States: articles of incorporation, a business licence, or the IRS EIN confirmation letter.',
        'Canada and Australia: provincial or federal registration, or ABN registration.'])),
  S('Why it gets rejected', ul(['The legal name has a different form, such as Ltd versus Limited.', 'The address on the document differs from the one entered.', 'The document is cropped, expired or unreadable.', 'The website does not mention the business.'])),
  S('Steps', ol(['In Business Settings open Security Center and start verification.', 'Enter the legal name exactly as on the document.', 'Upload one clear document and confirm by email, phone or domain.', 'If rejected, read the reason and fix only that.'])),
 ],
 [('Can I use a sole trader document?', 'Yes, if it is official and shows the trading name and your details.'),
  ('How many times can I try?', 'Meta does not publish a fixed number. Fix the reason each time rather than resubmitting the same document.'),
  ('Does verification lift an ad restriction?', 'Sometimes it is the step Meta asks for. Check what Account Quality says.')],
 ['UK, EU and US businesses setting up verification.', 'Agencies verifying a client portfolio.', 'Anyone whose verification was rejected.'])

page('meta-business-portfolio-disabled-all-ad-accounts-lost', 'ad', 'Business Portfolio Disabled: All Ad Accounts Lost',
 'Your Meta business portfolio was disabled and every ad account and Page inside it went with it. What to check and how to request a review.',
 'Your whole Meta business portfolio was disabled?', 'Business portfolio disabled',
 'When the portfolio itself is restricted, every asset inside it stops. The review has to start at the portfolio level.',
 'If your Meta business portfolio is disabled, every ad account inside it stops, even if each one looked healthy. Open Business Support Home, select the portfolio, and read the reason. Check that the admins’ own profiles are not restricted, complete any verification step shown, and request a review once as an admin.',
 [('Start at the portfolio', 'That is where the restriction sits.'), ('Check admin profiles', 'A restricted admin can be the cause.'), ('One review', 'With accurate details.')],
 [S('Steps', ol(['Open Business Support Home and select the business portfolio.', 'Read the reason and any steps listed under What you can do.', 'Check each admin profile for its own restriction.',
        'Complete business verification if requested.', 'Request a review and note the date.'])),
  S('Clients and agencies', 'If you are an agency, client-owned ad accounts shared with your portfolio are often unaffected in the client’s own portfolio. Ask clients to check from their side. See %s.' % A('/agency-business-portfolio-restricted-client-accounts/', 'agency portfolio restricted')),
 ],
 [('Can I move ad accounts out of a disabled portfolio?', 'Not while it is disabled.'),
  ('Should I create a new portfolio?', 'Creating a new one to get around the restriction can make things worse.'),
  ('What if the review is rejected?', 'See what to do after a rejected appeal.')],
 ['Businesses with several ad accounts in one portfolio.', 'Agencies whose own portfolio was disabled.', 'Ecommerce brands mid-campaign.'])

page('meta-ad-account-disabled-us-small-business-first-steps', 'ad', 'US Small Business: Meta Ad Account Disabled, First Steps',
 'A short, practical order of steps for US small businesses whose Meta ad account was disabled: Account Quality, billing, review and backup channels.',
 'Your US small business ad account was disabled. Where do you start?', 'US small business, ad account disabled',
 'Small businesses rarely have a dedicated Meta contact. This is the order that gives the review the best footing.',
 'If your Meta ad account is disabled, open Account Quality in Business Support Home and read the exact reason. Check billing, landing pages and business verification, fix what is listed, then request a review once as an admin. Meanwhile, keep sales going through Google Ads, email and your site.',
 [('Read Account Quality', 'The reason is listed there.'), ('Fix, then review', 'Once, as an admin.'), ('Keep selling', 'Other channels keep revenue moving.')],
 [S('Checklist', ol(['Screenshot the notice and the ad account ID.', 'Check the payment method and any failed charges.', 'Check that the landing page works and matches the ad.', 'Complete business verification if prompted.', 'Request a review in Account Quality.'])),
  S('What US owners ask', 'Many owners ask whether a state attorney general or FTC complaint helps. These complaints are logged but do not decide individual ad accounts. See %s.' % A('/ftc-and-state-attorney-general-complaint-meta-account/', 'FTC and state AG complaints')),
 ],
 [('Do I need an agency to get a review?', 'No. Any admin can request a review.'),
  ('Will Meta call me?', 'Some advertisers get chat or email support. Meta does not offer phone support to most small businesses.'),
  ('Can I open a new ad account?', 'Not to get around a disabled one.')],
 ['US small businesses and local services.', 'Ecommerce stores advertising on Meta.', 'Owners running their own ads.'], area='US')

page('meta-ad-account-disabled-uk-business-first-steps', 'ad', 'UK Business: Meta Ad Account Disabled, What to Do',
 'Practical first steps for UK businesses whose Meta ad account was disabled, including VAT and Companies House details for verification.',
 'Your UK business ad account was disabled?', 'UK business, ad account disabled',
 'UK businesses follow the same review as anyone else, with UK documents for verification.',
 'If your UK business’s Meta ad account is disabled, read the reason in Account Quality, check billing and your landing page, and complete business verification with a Companies House certificate or VAT document if asked. Then request a review once as an admin. UK GDPR also lets you request the data Meta holds.',
 [('Account Quality', 'Read the reason.'), ('UK documents', 'Companies House or VAT.'), ('Data rights', 'A subject access request is open to you.')],
 [S('Checklist', ol(['Screenshot the notice and the ad account ID.', 'Check the card and billing address match the business.', 'Verify the business with Companies House details if prompted.', 'Request a review once.'])),
  S('Other UK routes', 'For data concerns, see %s. For fraud through a hacked account, report to Action Fraud.' % SAR),
 ],
 [('Does the EU DSA apply to UK businesses?', 'No, not for UK-based accounts.'),
  ('Can I complain to Ofcom?', 'Ofcom regulates online safety duties, not individual ad account decisions.'),
  ('Will a UK phone number help?', 'Accurate, matching details help more than the number itself.')],
 ['UK limited companies and sole traders.', 'UK agencies with client accounts.', 'Ecommerce brands selling in the UK.'], area='GB')

page('instagram-username-claim-with-uk-or-eu-trademark', 'user', 'Instagram Username Claim With a UK or EU Trademark',
 'How a UKIPO or EUIPO trademark can support a claim to an Instagram username, what Instagram looks at, and when it does not help.',
 'Have a UK or EU trademark and someone else has the Instagram username?', 'Username claim with a UK or EU trademark',
 'A registered trademark is one of the strongest supports for a username claim, but only when the account is using the name in a way that infringes it.',
 'A UKIPO or EUIPO registered trademark can support a claim to an Instagram username when the account holding it uses the name in a way that infringes your mark, such as selling similar goods or impersonating the brand. Instagram looks at the registration, the classes, and how the account uses the name.',
 [('Registered mark', 'UKIPO or EUIPO registration number.'), ('Matching classes', 'Goods or services must overlap.'), ('How the name is used', 'Infringement or impersonation.')],
 [S('What to prepare', ul(['The registration number and certificate.', 'The classes the mark covers.', 'Screenshots of the account and how it uses the name.', 'Proof you use the brand: website, products, invoices.'])),
  S('When it may not help', ul(['The account is inactive but not infringing.', 'The mark is in unrelated classes.', 'The name is a common word.'])),
 ],
 [('Does a pending application count?', 'A registered mark is much stronger than a pending one.'),
  ('Can I claim a handle used by a fan page?', 'Only if it misleads people or infringes the mark.'),
  ('What if the claim fails?', 'See the refund policy for username claims.')],
 ['UK and EU brands with a registered mark.', 'Founders who rebranded.', 'Agencies acting for brand clients.'], area=['GB', 'EU'])

page('instagram-username-claim-with-us-trademark', 'user', 'Instagram Username Claim With a US (USPTO) Trademark',
 'Using a USPTO registered trademark to support a claim to an Instagram handle: what to prepare and how Instagram weighs it.',
 'Have a USPTO trademark and the Instagram handle is taken?', 'Username claim with a US trademark',
 'US brands with a registered mark have a solid starting point. Here is what Instagram looks at.',
 'A USPTO registered trademark can support an Instagram username claim when the account holding the handle uses it in a way that infringes your mark or impersonates your brand. Prepare the registration number, the classes, screenshots of how the account uses the name, and proof you trade under the brand in the US.',
 [('Registration number', 'From the USPTO record.'), ('Classes', 'Goods and services must overlap.'), ('Evidence of use', 'Website, products, invoices.')],
 [S('What to prepare', ul(['The USPTO registration number and certificate.', 'Screenshots of the account and its use of the name.', 'Your website and product pages.', 'A short timeline of the brand.'])),
  S('Limits', ul(['Supplemental Register marks carry less weight.', 'Common words are harder.', 'Inactive accounts that do not infringe are handled differently.'])),
 ],
 [('Do state trademarks count?', 'They carry less weight than a federal registration.'),
  ('Does Unbanz file the trademark?', 'No. We work with a mark you already hold.'),
  ('What happens to the current holder?', 'Instagram decides whether to move the handle.')],
 ['US brands with a federal trademark.', 'US startups that rebranded.', 'Agencies for US brand clients.'], area='US')

page('brand-name-taken-on-instagram-and-tiktok', 'user', 'Your Brand Name Is Taken on Instagram and TikTok',
 'Your brand name is already taken on Instagram and TikTok. Which platform routes exist for brands, what helps, and what to do meanwhile.',
 'Your brand name is taken on Instagram and TikTok?', 'Brand name taken on two platforms',
 'Both platforms handle trademarks and impersonation, but through different forms and rules.',
 'If your brand name is taken on Instagram and TikTok, check how each account uses it. Instagram and TikTok both accept trademark and impersonation reports from rights holders. A registered mark and clear proof of use help on both. Inactive accounts that do not infringe are harder, and each platform decides separately.',
 [('Check each account', 'Active, inactive or infringing.'), ('Trademark helps', 'On both platforms.'), ('Separate decisions', 'One does not affect the other.')],
 [S('Instagram', 'Use the trademark or impersonation report, or an inactive username route where it fits. See %s.' % A('/trademark-username-claim/', 'trademark username claims')),
  S('TikTok', 'TikTok has its own intellectual property report form for trademark holders. It looks at how the account uses the name.'),
  S('Meanwhile', 'Use a close variant consistently, such as adding shop or official, and link both from your website so customers find the real account.'),
 ],
 [('Will winning on Instagram help on TikTok?', 'Not formally. Each platform decides on its own.'),
  ('Is buying the handle an option?', 'Both platforms ban buying and selling usernames.'),
  ('What if the holder is a fan?', 'Fan accounts that do not mislead are usually allowed.')],
 ['Brands launching on social media.', 'Founders after a rebrand.', 'Agencies running launches.'])

page('snapchat-account-locked-temporary-or-permanent', 'snap', 'Snapchat Locked: Temporary or Permanent, How to Tell',
 'How to tell whether a Snapchat lock is temporary or permanent from the message, how long temporary locks usually last, and what to do.',
 'Is your Snapchat lock temporary or permanent?', 'Temporary or permanent lock',
 'The message on the login screen tells you which one you have. The next steps are different.',
 'Snapchat shows the type of lock when you log in. A temporary lock usually lifts after a period, often 24 hours, and you can unlock it from accounts.snapchat.com once it ends. A permanent lock means the account was banned for serious or repeated violations, and the only route is Snapchat’s support form.',
 [('Read the message', 'It says which one.'), ('Temporary', 'Wait, then unlock.'), ('Permanent', 'Support form only.')],
 [S('Temporary lock', ol(['Remove third-party apps and plugins.', 'Wait out the period shown.', 'Log in at accounts.snapchat.com and choose Unlock.'])),
  S('Permanent lock', ol(['Use the Snapchat support form for locked accounts.', 'Explain the account use briefly.', 'Do not create new accounts on the same device.'])),
 ],
 [('Can a permanent lock be reversed?', 'Rarely, through support. See %s.' % 'our page on permanently banned Snapchat accounts'),
  ('Why is there no unlock button?', 'The lock period may not have ended, or the lock is permanent.'),
  ('Does a VPN cause locks?', 'It can contribute when combined with other signals.')],
 ['Snapchat users after a lock.', 'Parents helping a teen.', 'Creators with Public Profiles.'])

page('instagram-disabled-uk-what-to-do', 'igsusp', 'Instagram Disabled in the UK: What to Do Next',
 'Your Instagram account was disabled and you are in the UK. The in-app appeal, UK data rights, Action Fraud for hacks, and what to avoid.',
 'Instagram disabled your account and you are in the UK?', 'Instagram disabled, UK',
 'UK users have the same in-app appeal as anyone, plus UK GDPR data rights. The EU DSA no longer applies in the UK.',
 'If Instagram disabled your account in the UK, appeal from the notice, once, with accurate details. If the account was hacked first, also report to Action Fraud. UK GDPR lets you request your personal data from Meta, and complaints about data handling go to the ICO. The EU Digital Services Act does not cover UK users.',
 [('Appeal in the app', 'The main route.'), ('Data access', 'UK GDPR right of access.'), ('Hacked?', 'Report to Action Fraud too.')],
 [S('Steps', ol(['Open the notice and appeal. Confirm your identity if asked.', 'If it was hacked first, say so with the date.', 'Request your data from Meta if you want your photos or the records.', 'Keep every notice with its date.'])),
  S('UK routes', 'See %s and %s.' % (SAR, A('/ico-complaint-meta-account-data/', 'ICO complaints'))),
 ],
 [('Is there a UK phone number for Instagram?', 'Instagram does not offer phone support in the UK. Be wary of numbers found online.'),
  ('Can I use Appeals Centre Europe?', 'Only if you are located in the EU.'),
  ('Does Ofcom deal with bans?', 'Ofcom oversees online safety duties, not individual decisions.')],
 ['UK Instagram users after a ban.', 'UK small businesses.', 'UK creators.'], area='GB')

page('instagram-disabled-usa-what-to-do', 'igsusp', 'Instagram Disabled in the US: Your Options',
 'Your Instagram account was disabled and you are in the US. The appeal, Meta Verified support, FTC and IC3 for hacks, and what to avoid.',
 'Instagram disabled your account and you are in the US?', 'Instagram disabled, US',
 'In the US the in-app appeal is the main route. Consumer agencies help with fraud, not with bans.',
 'If Instagram disabled your account in the US, appeal once from the notice and confirm your identity if asked. If you have Meta Verified on a linked account, open support from there. If the account was hacked or used for fraud, report to IC3 and the FTC. These agencies log complaints but do not restore accounts.',
 [('Appeal', 'Once, accurately.'), ('Meta Verified', 'From a linked active account.'), ('Fraud reports', 'IC3 and FTC.')],
 [S('Steps', ol(['Open the notice and appeal.', 'Complete ID or video selfie checks if asked.', 'If hacked, report at IC3.gov and ReportFraud.ftc.gov.', 'Save every notice and date.'])),
  S('Related', '%s, %s.' % (A('/ftc-and-state-attorney-general-complaint-meta-account/', 'FTC and state AG complaints'), A('/meta-verified-support-how-to-use/', 'Meta Verified support'))),
 ],
 [('Can I call Instagram in the US?', 'Instagram does not offer phone support. Numbers online claiming to be Instagram are often scams.'),
  ('Can I sue Instagram?', 'Talk to a lawyer. Meta’s terms include rules on where disputes are heard.'),
  ('Does my state have special rules?', 'Some states have consumer protection laws, but none give a general right to restoration.')],
 ['US Instagram users after a ban.', 'US small businesses and creators.', 'Parents of US teens.'], area='US')

page('instagram-disabled-eu-what-to-do', 'igsusp', 'Instagram Disabled in the EU: Appeal and DSA Routes',
 'Your Instagram account was disabled and you live in the EU. The in-app appeal, the DSA complaint, Appeals Centre Europe, and GDPR access.',
 'Instagram disabled your account and you live in the EU?', 'Instagram disabled, EU',
 'People in the EU have the strongest set of routes after a ban. Use them in order.',
 'If Instagram disabled your account and you live in the EU, appeal in the app first. Under the Digital Services Act you can then take the final decision to a certified dispute body such as Appeals Centre Europe within six months. GDPR also gives you a right to a copy of your personal data.',
 [('Appeal in the app', 'Step one.'), ('Dispute body', 'Within six months.'), ('GDPR access', 'Your data, on request.')],
 [S('Order of steps', ol(['Appeal from the notice.', 'Save the final decision.', 'Submit to %s.' % ACE, 'Request your data if you want it.', 'Complain to your national Digital Services Coordinator if the platform does not follow the rules.'])),
  S('Countries', 'This applies in France, Germany, the Netherlands, Ireland, Belgium, the Nordic EU members and every other EU country. Norway, Iceland and Switzerland are outside the EU and have their own rules.'),
 ],
 [('Do I need a lawyer?', 'No, the dispute body route is built for individuals.'),
  ('What language can I use?', 'Appeals Centre Europe works in English, French, German, Spanish, Italian, Polish and Dutch.'),
  ('Does it help with a hack?', 'It reviews decisions, such as the ban that followed a hack.')],
 ['EU Instagram users after a ban.', 'EU businesses and creators.', 'People who had an appeal rejected.'], area='EU')

page('facebook-page-restricted-small-business-what-to-do', 'fbdis', 'Facebook Page Restricted: Small Business Steps',
 'Your small business Facebook Page is restricted or unpublished. How to read Page status, fix the issue and request a review.',
 'Your small business Facebook Page was restricted?', 'Small business Page restricted',
 'Page restrictions show in Page status. Reading it carefully saves a wasted review.',
 'If your small business Facebook Page is restricted, open Page status or Account Quality from the Page in Meta Business Suite. It shows what was restricted and why. Remove or edit the content listed, check the Page name and category match the business, and request a review where the option is shown.',
 [('Open Page status', 'It lists the reason.'), ('Fix the content', 'Remove or edit what is listed.'), ('Request a review', 'Where shown.')],
 [S('Steps', ol(['Open the Page, Settings, then Page status.', 'Read each issue and the related post.', 'Fix, then request a review.', 'Check that admins’ own profiles are in good standing.'])),
  S('If the Page is unpublished', 'Unpublished Pages can sometimes be appealed from the notice. See %s.' % A('/guides/facebook-page-restricted/', 'Facebook Page restricted')),
 ],
 [('Can customers still see the Page?', 'Depends on the restriction. Some only limit reach or ads.'),
  ('Will a new Page help?', 'Not if it duplicates a restricted Page.'),
  ('Can I still advertise?', 'Often not while the Page is restricted.')],
 ['Small business Page owners.', 'Local services and shops.', 'Agencies managing local Pages.'])

page('business-and-creator-account-help', 'hubbiz', 'Business and Creator Account Help: Instagram, Facebook',
 'Help for businesses, brands and creators with disabled, hacked or restricted Instagram, Facebook, Snapchat and TikTok accounts, and Meta ads.',
 'Your business or creator account is down. Start here.', 'Business and creator account help',
 'Pick the situation closest to yours. Each page starts with a direct answer and the official steps.',
 'When a business or creator account is disabled, hacked or restricted, start with the in-app appeal or recovery flow, save every notice with its date, and do not open replacement accounts. Then use the guide for your situation below. In the EU and UK, you also have legal routes. Terms are agreed with you before any work starts.',
 [('Disabled', 'Appeal and keep customers.'), ('Hacked', 'First hour and admin access.'), ('Rights', 'EU, UK and US routes.')],
 [], [('Do you help with TikTok?', 'Our main work is Instagram, Facebook, Snapchat and Meta ads. For TikTok we can tell you which official route fits.'),
  ('Is this legal advice?', 'No. The rights pages are general information.'),
  ('Do I need to be a business?', 'No. Personal accounts are welcome too.')],
 ['Small businesses, brands, creators and agencies.', 'People in the US, UK, EU, Canada, Australia and the Gulf.', 'Anyone whose account is part of their income.'])
